{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8081
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 8435,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 8799,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 9272,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 8324,
      "weight": 9,
      "health_check": "/healthz"
    },
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 9064,
      "weight": 9,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/orders/settings",
      "upstream": "orders",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 1
    },
    {
      "path": "/api/v1/reviews/settings",
      "upstream": "reviews",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 5000,
      "retries": 3
    },
    {
      "path": "/api/v1/reviews/history",
      "upstream": "reviews",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/carts/history",
      "upstream": "carts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2000,
      "retries": 0
    },
    {
      "path": "/api/v1/reviews/batch",
      "upstream": "reviews",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/search/tokens",
      "upstream": "search",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/search/status",
      "upstream": "search",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/inventory/summary",
      "upstream": "inventory",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2000,
      "retries": 2
    },
    {
      "path": "/api/v1/reviews/lookup",
      "upstream": "reviews",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 2
    }
  ]
}

